class Solution {
public:
    bool primeSubOperation(std::vector<int>& nums) {
        std::vector<bool> is_prime(1005, true);
        is_prime[0] = is_prime[1] = false;
        std::vector<int> primes;
        for (int p = 2; p < 1005; ++p) {
            if (is_prime[p]) {
                primes.push_back(p);
                for (int m = p * p; m < 1005; m += p) {
                    is_prime[m] = false;
                }
            }
        }
        int prev = 0;
        for (int x : nums) {
            int best_p = 0;
            for (int p : primes) {
                if (p >= x) break;
                if (x - p > prev) best_p = p;
            }
            x -= best_p;
            if (x <= prev) return false;
            prev = x;
        }
        return true;
    }
};

class Solution {
    public boolean primeSubOperation(int[] nums) {
        boolean[] isPrime = new boolean[1005];
        java.util.Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        java.util.List<Integer> primes = new java.util.ArrayList<>();
        for (int p = 2; p < 1005; p++) {
            if (isPrime[p]) {
                primes.add(p);
                for (int m = p * p; m < 1005; m += p) {
                    isPrime[m] = false;
                }
            }
        }
        int prev = 0;
        for (int x : nums) {
            int bestP = 0;
            for (int p : primes) {
                if (p >= x) break;
                if (x - p > prev) bestP = p;
            }
            x -= bestP;
            if (x <= prev) return false;
            prev = x;
        }
        return true;
    }
}

